"""final_evaluation spine: serial play of final checkpoints and both baselines on FINAL_SEEDS.

`compare_baselines` and `verdict` are thickened by their own tasks, so these tests replace them
(and the other steps' stubs) with recording doubles.
"""

import importlib.util
import json
import sys
from collections import Counter
from collections.abc import Mapping, Sequence
from dataclasses import dataclass, replace
from pathlib import Path
from typing import Any, Literal

import numpy as np
import pytest

from rllab.core import (
    FINAL_SEEDS,
    ActionSpace,
    Array,
    Direction,
    Episode,
    EpisodeResult,
    Policy,
    TeamSpec,
    World,
    WorldSpec,
)
from rllab.evaluate import Comparison, Summary, Verdict
from rllab.evaluate.final import play, summary
from rllab.runlog import Checkpoint, EvalPoint, Run

CONTRACTS = Path(__file__).parents[2] / "contracts"
RUN_SCORES = {
    "snake-s1": 11.0,
    "snake-s2": 12.0,
    "snake-s3": 13.0,
    "snake-s4": 14.0,
    "snake-s5": 15.0,
}
RANDOM_SCORE = 1.0
RULE_SCORE = 8.0
Baseline = Literal["random", "rule"]


def load_kit() -> Any:
    if "contracts_kit" not in sys.modules:
        spec = importlib.util.spec_from_file_location("contracts_kit", CONTRACTS / "kit.py")
        assert spec is not None
        assert spec.loader is not None
        module = importlib.util.module_from_spec(spec)
        sys.modules["contracts_kit"] = module
        spec.loader.exec_module(module)
    return sys.modules["contracts_kit"]


@dataclass(frozen=True)
class Scripted:
    """A policy double whose episodes score `score` for its team; `kind` names what made it."""

    kind: str
    score: float

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        return np.zeros(len(obs), dtype=np.int64)


@dataclass(frozen=True)
class FakeWorld:
    spec: WorldSpec


@dataclass
class Played:
    """Every episode's seed and policy kind per team, and every compare_baselines call."""

    episodes: list[tuple[int, dict[str, str]]]
    compared: list[tuple[str, Array, Mapping[Baseline, Array]]]


@pytest.fixture
def kit() -> Any:
    return load_kit()


@pytest.fixture
def runs(kit: Any, tmp_path: Path) -> list[Run]:
    found: list[Run] = kit.fake("runlog.find_runs")(tmp_path, "snake", "default")
    return found


def load_policy(ckpt: Checkpoint, team: str, spec: WorldSpec) -> Policy:
    return Scripted(f"learned:{ckpt.run}:{ckpt.pct}", RUN_SCORES[ckpt.run])


def random_policy(action: ActionSpace) -> Policy:
    return Scripted("random", RANDOM_SCORE)


def rule_for(world: str, variant: str, team: str) -> Policy:
    return Scripted("rule", RULE_SCORE)


def verdict(
    run_means: Mapping[str, float],
    rule_mean: float,
    comparisons: Sequence[Comparison],
    direction: Direction,
) -> Verdict:
    return Verdict(bool(comparisons), (), max(0, 5 - len(run_means)))


@pytest.fixture
def played(monkeypatch: pytest.MonkeyPatch, runs: list[Run]) -> Played:
    log = Played([], [])
    world = FakeWorld(runs[0].record.spec)

    def make(name: str, variant: str) -> World:
        assert (name, variant) == ("snake", "default")
        return world

    def play_episode(world: World, policies: Mapping[str, Policy], seed: int) -> Episode:
        scripted = {team: p for team, p in policies.items() if isinstance(p, Scripted)}
        assert scripted.keys() == {t.name for t in world.spec.teams}
        log.episodes.append((seed, {team: p.kind for team, p in scripted.items()}))
        scores = {team: p.score for team, p in scripted.items()}
        return Episode(EpisodeResult(seed, 1, scores, scores, {}), None, hit_step_limit=False)

    def compare_baselines(
        team: str,
        learned: Array,
        baselines: Mapping[Baseline, Array],
        direction: Direction,
        *,
        rng: np.random.Generator,
    ) -> tuple[Comparison, ...]:
        log.compared.append((team, learned, baselines))
        mean = float(learned.mean())
        return tuple(
            Comparison(name, team, mean, float(b.mean()), mean - float(b.mean()), 0.01, 0.02, True)
            for name, b in baselines.items()
        )

    monkeypatch.setattr(play, "make", make)
    monkeypatch.setattr(play, "load_policy", load_policy)
    monkeypatch.setattr(play, "RandomPolicy", random_policy)
    monkeypatch.setattr(play, "rule_for", rule_for)
    monkeypatch.setattr(play, "play_episode", play_episode)
    monkeypatch.setattr(play, "compare_baselines", compare_baselines)
    monkeypatch.setattr(summary, "verdict", verdict)
    return log


def test_final_evaluation_plays_700_episodes_on_the_final_seeds(
    runs: list[Run], played: Played, tmp_path: Path
) -> None:
    play.final_evaluation(runs, tmp_path)

