"""Intent tests for the EVAL-04 paired permutation test with Holm correction (M1-T25, PL-06).

Designed with the null-hypothesis-testing skill:
- hypothesis: the trained agent scores better than the baseline;
- H0: the learned mean score is no better than the baseline's; H1: it is better, in the
  world's score direction (one-sided);
- statistic: mean over seeds of (learned score averaged over runs) minus baseline score,
  signed so positive means better;
- null: swap learned and baseline labels within each held-out seed (paired permutation,
  10,000 permutations);
- alpha = 0.05 after Holm across the 2 baseline comparisons.

The synthetic generators below build inputs only (TC-16/17/18 "Source"); every expected
outcome is read from the TC fixtures.
"""

import json
from pathlib import Path
from typing import Any

import numpy as np
import pytest

from rllab.core import Array, Direction
from rllab.evaluate import Comparison, compare
from rllab.evaluate.final.stats import compare_baselines, holm

FIXTURES = Path(__file__).resolve().parents[2] / "fixtures" / "rllab"
TEAM = "snake"


def _load(case: str) -> tuple[dict[str, Any], dict[str, Any]]:
    folder = FIXTURES / case
    inputs = json.loads((folder / "input.json").read_text())
    expected = json.loads((folder / "expected.json").read_text())
    return inputs, expected


def planted_scores(
    *, runs: int, seeds: int, learned: float, random: float, rule: float, sd: float, seed: int
) -> tuple[Array, dict[str, Array]]:
    """Learned runs x seeds and one score per seed per baseline, with planted means."""
    rng = np.random.default_rng(seed)
    learned_scores = rng.normal(learned, sd, size=(runs, seeds))
    baselines = {
        "random": rng.normal(random, sd, size=seeds),
        "rule": rng.normal(rule, sd, size=seeds),
    }
    return learned_scores, baselines


def null_scores(
    *, runs: int, seeds: int, mean: float, sd: float, seed: int
) -> tuple[Array, dict[str, Array]]:
    """Learned and both baselines drawn from one distribution: H0 holds."""
    return planted_scores(
        runs=runs, seeds=seeds, learned=mean, random=mean, rule=mean, sd=sd, seed=seed
    )


def _by_baseline(comparisons: tuple[Comparison, ...]) -> dict[str, Comparison]:
    found = {c.baseline: c for c in comparisons}
    assert set(found) == {"random", "rule"}
    assert len(comparisons) == 2
    return found


def _planted(inputs: dict[str, Any]) -> tuple[Array, dict[str, Array]]:
    return planted_scores(
        runs=inputs["runs"],
        seeds=inputs["seeds"],
        learned=inputs["learned"],
        random=inputs["random"],
        rule=inputs["rule"],
        sd=inputs["sd"],
        seed=inputs["seed"],
    )


@pytest.mark.intent
def test_tc16_planted_improvement_rejects_both_nulls() -> None:
    inputs, expected = _load("TC-16")
    learned, baselines = _planted(inputs)
    direction: Direction = inputs["direction"]
    comparisons = compare_baselines(
        TEAM, learned, baselines, direction, rng=np.random.default_rng(inputs["seed"])
    )
    found = _by_baseline(comparisons)
    for name in ("random", "rule"):
        c = found[name]
        assert c.team == TEAM
        assert c.rejected is expected[name]["rejected"]
        assert np.sign(c.difference) == expected[name]["difference_sign"]
        assert c.p_holm >= c.p_raw
        assert c.p_holm < expected["alpha"]
        assert c.learned_mean == pytest.approx(float(learned.mean()), rel=1e-9)
        assert c.baseline_mean == pytest.approx(float(baselines[name].mean()), rel=1e-9)
        assert c.difference == pytest.approx(c.learned_mean - c.baseline_mean, rel=1e-9)


@pytest.mark.intent
def test_tc16_compare_returns_positive_difference_and_small_p() -> None:
    inputs, expected = _load("TC-16")
    learned, baselines = _planted(inputs)
    direction: Direction = inputs["direction"]
    for name in ("random", "rule"):
        difference, p = compare(
            learned,
            baselines[name],
            direction,
            permutations=inputs["permutations"],
            rng=np.random.default_rng(inputs["seed"]),
        )
        assert np.sign(difference) == expected[name]["difference_sign"]
        assert difference == pytest.approx(
            float(learned.mean(axis=0).mean() - baselines[name].mean()), rel=1e-9
        )
        assert 0.0 < p < expected["alpha"]


@pytest.mark.intent
def test_tc17_pure_noise_keeps_both_nulls_on_almost_every_seed() -> None:
    inputs, expected = _load("TC-17")
    direction: Direction = inputs["direction"]
    rejecting = 0
    for seed in inputs["generator_seeds"]:
        learned, baselines = null_scores(
            runs=inputs["runs"],
            seeds=inputs["seeds"],
            mean=inputs["mean"],
            sd=inputs["sd"],
            seed=seed,
        )
        found = _by_baseline(
            compare_baselines(TEAM, learned, baselines, direction, rng=np.random.default_rng(seed))
        )
        for c in found.values():
            assert 0.0 < c.p_raw <= 1.0
            assert c.p_raw <= c.p_holm <= 1.0
            assert c.rejected == (c.p_holm < expected["alpha"])
        if any(c.rejected for c in found.values()):
            rejecting += 1
    assert rejecting <= expected["max_rejecting_seeds"]


@pytest.mark.intent
@pytest.mark.parametrize("direction", ["lower", "higher"])
def test_tc18_lower_is_better_tests_in_the_right_direction(direction: Direction) -> None:
    inputs, expected = _load("TC-18")
    assert direction in inputs["directions"]
    learned, baselines = _planted(inputs)
    found = _by_baseline(
        compare_baselines(
            TEAM, learned, baselines, direction, rng=np.random.default_rng(inputs["seed"])
        )
    )
    for name in ("random", "rule"):
        want = expected[direction][name]
        c = found[name]
        assert c.rejected is want["rejected"]
        if "difference_sign" in want:
            assert np.sign(c.difference) == want["difference_sign"]
        else:
            assert c.p_holm >= expected["alpha"]


@pytest.mark.intent
def test_tc18_lower_direction_signs_difference_as_baseline_minus_learned() -> None:
    inputs, expected = _load("TC-18")
    learned, baselines = _planted(inputs)
    difference, p = compare(
        learned,
        baselines["random"],
        "lower",
        permutations=inputs["permutations"],
        rng=np.random.default_rng(inputs["seed"]),
    )
    assert np.sign(difference) == expected["lower"]["random"]["difference_sign"]
    assert difference == pytest.approx(
        float(baselines["random"].mean() - learned.mean(axis=0).mean()), rel=1e-9
    )
    assert p < expected["alpha"]


@pytest.mark.intent
@pytest.mark.parametrize("index", [0, 1])
def test_tc19_holm_step_down_on_two_p_values(index: int) -> None:
    inputs, expected = _load("TC-19")
    raw = inputs["cases"][index]
    want = expected["cases"][index]
    assert raw == want["raw"]
    adjusted = [float(p) for p in holm(raw)]
    assert adjusted == pytest.approx(want["holm"], abs=expected["tol"])
    assert [p < inputs["alpha"] for p in adjusted] == want["rejected"]


@pytest.mark.intent
@pytest.mark.parametrize("index", [0, 1])
def test_tc19_holm_keeps_input_order(index: int) -> None:
    inputs, expected = _load("TC-19")
    raw = list(reversed(inputs["cases"][index]))
    want = list(reversed(expected["cases"][index]["holm"]))
    adjusted = [float(p) for p in holm(raw)]
    assert adjusted == pytest.approx(want, abs=expected["tol"])


@pytest.mark.intent
def test_compare_rejects_mismatched_seed_counts() -> None:
    inputs, _ = _load("TC-16")
    learned, baselines = _planted(inputs)
    with pytest.raises(ValueError, match=r"(?i)seed"):
        compare(
            learned,
            baselines["random"][:-1],
            "higher",
            permutations=inputs["permutations"],
            rng=np.random.default_rng(0),
        )

